function page114(){if(!super114())return denied9();const s=model114(),users=s.users.filter(u=>(ui114.status==='all'||u.status===ui114.status)&&(ui114.role==='all'||u.role===ui114.role||ui114.role==='super'&&u.super)&&(u.name+' '+u.email).toLowerCase().includes(ui114.q.toLowerCase())),roles=s.roles.filter(r=>(ui114.archived||!r.archived)&&(r.name+' '+r.description).toLowerCase().includes(ui114.q.toLowerCase()));
return `<div class="staff-page114"><header class="heading114"><div><small>STAFF / AKUN & KEWENANGAN</small><h1>Staff & Akses</h1><p>Kelola akun, kewenangan, dan kesinambungan pekerjaan tim.</p></div>${B114(ui114.tab==='staff'?'Undang Staff':'Buat Peran',ui114.tab==='staff'?'invite':'new-role','','primary')}</header><div class="summary114"><article class="brand114"><span>Staff aktif</span><strong>${s.users.filter(u=>!u.super&&u.status==='active').length}</strong><small>Super Admin dihitung terpisah</small></article><article><span>Menunggu aktivasi</span><strong>${s.users.filter(u=>u.status==='invited').length}</strong><small>Undangan dapat dikirim ulang atau dicabut</small></article><article><span>Perlu pengalihan</span><strong>${pending114().length}</strong><small>Pekerjaan mempertahankan tahap dan tenggat</small>${pending114().length?B114('Lihat pekerjaan ↗','handoffs','','text'):''}</article></div><div class="switch104 tabs114" role="tablist" aria-label="Staff dan peran">${['staff','roles'].map(k=>`<button type="button" role="tab" aria-selected="${ui114.tab===k}" class="${ui114.tab===k?'active':''}" data-s114="tab" data-id="${k}">${k==='staff'?'Daftar Staff':'Peran & Izin'}</button>`).join('')}</div><div class="filters114"><label class="search114"><span class="sr-only">Cari staff atau peran</span><input id="q114" placeholder="${ui114.tab==='staff'?'Cari nama atau email staff…':'Cari peran…'}" value="${E(ui114.q)}"></label>${ui114.tab==='staff'?`<select id="status114" aria-label="Filter status"><option value="all">Semua status</option>${Object.entries(names114).map(([v,l])=>`<option value="${v}" ${ui114.status===v?'selected':''}>${l}</option>`).join('')}</select><select id="role114" aria-label="Filter peran"><option value="all">Semua peran</option><option value="super" ${ui114.role==='super'?'selected':''}>Super Admin</option>${s.roles.map(r=>`<option value="${E(r.id)}" ${ui114.role===r.id?'selected':''}>${E(r.name)}</option>`).join('')}</select>`:`<label class="check114"><input id="archived114" type="checkbox" ${ui114.archived?'checked':''}>Tampilkan arsip</label>`}${B114('Reset filter','reset','','text')}</div><section class="list114">${ui114.tab==='staff'?`<div class="list-head114"><span>STAFF</span><span>PERAN & CAKUPAN</span><span>STATUS AKUN</span><span>PEKERJAAN AKTIF</span></div>${users.map(u=>`<button type="button" class="staff-row114" data-s114="staff" data-id="${u.id}"><div class="person114">${avatar114(u)}<div><strong>${E(u.name)}</strong><small>${E(u.email)}</small></div></div><div><strong>${E(roleName114(u))}</strong><small>${E(scopeName114(u))}</small></div><div>${status114(u)}</div><div class="row-end114"><span>${jobs114().filter(j=>j.handler===u.id&&!j.closed).length}</span><i>↗</i></div></button>`).join('')||'<p class="empty114">Tidak ada staff yang sesuai filter.</p>'}`:`<div class="role-list114">${roles.map(r=>`<button type="button" class="role-row114" data-s114="role" data-id="${r.id}"><span class="role-icon114">${icon('shield')}</span><div><strong>${E(r.name)}</strong><p>${E(r.description||'Belum ada penjelasan peran.')}</p></div><span>${s.users.filter(u=>u.role===r.id).length} staff<small>${r.permissions.length} izin${r.archived?' · Diarsipkan':''}</small></span><i>↗</i></button>`).join('')||'<p class="empty114">Belum ada peran pada tampilan ini.</p>'}</div>`}</section><div class="migration114">${icon('shield')}<div><strong>Akses akun lama dipertahankan sebagai dasar.</strong><p>Setiap perubahan menampilkan izin dan pekerjaan yang terdampak sebelum disimpan.</p></div>${B114('Riwayat akses','history','','text')}</div>${newPermissions114()}<p class="scope-note">Undangan dan aktivasi menggunakan simulasi lokal. Tidak ada email undangan yang dikirim.</p></div>`}
function newPermissions114(){const ids=Staff114.catalog.filter(p=>!model114().reviewed.includes(p.id));return ids.length?`<section class="new-permissions114"><h3>${ids.length} izin baru perlu ditinjau</h3><p>${ids.map(p=>E(p.groupLabel+' · '+p.label)).join(', ')}</p>${B114('Tinjau izin baru','new-permissions','','small')}</section>`:''}
