function drawer114(title,body,footer='',id=''){let d=document.querySelector('#staff-drawer114');if(!d){d=document.createElement('dialog');d.id='staff-drawer114';d.className='drawer114 detail-panel111';d.addEventListener('click',e=>{if(e.target===d)close114()});d.addEventListener('cancel',()=>{ui114.draft=null;ui114.open=null});document.body.append(d)}d.innerHTML=`<header><div><small>STAFF & AKSES</small><h2>${E(title)}</h2></div>${B114('×','close','','close114')}</header><div class="drawer-body114">${body}</div>${footer?`<footer class="drawer-foot114">${footer}</footer>`:''}`;ui114.open=id;if(!d.open)d.showModal()}
