function staffDetail114(id){if(!super114())return;const u=user114(id);if(!u)return;const jobs=jobs114().filter(j=>j.handler===id&&!j.closed);drawer114(u.name,`<section class="hero114">${avatar114(u)}<div><h3>${E(u.name)}</h3><p>${E(u.email)}</p>${status114(u)}</div></section><dl class="facts114"><div><dt>Peran</dt><dd>${E(roleName114(u))}</dd></div><div><dt>Cakupan</dt><dd>${E(scopeName114(u))}</dd></div><div><dt>Bergabung</dt><dd>${u.joined?date10(u.joined):'Menunggu aktivasi'}</dd></div><div><dt>Pekerjaan aktif</dt><dd>${jobs.length}</dd></div></dl><section class="section114"><div class="section-head114"><h3>Akses saat ini</h3>${!u.super&&u.status!=='inactive'?B114('Ubah akses','edit-access',u.id,'small'):''}</div>${permissionList114(Staff114.effective(model114(),u))}${!u.super&&u.status==='active'?B114('Pratinjau akses','preview-user',u.id,'text'):''}${u.super?'<p class="note114">Kewenangan Super Admin mengikuti jenis akun khusus, bukan peran staff.</p>':''}</section><section class="section114"><h3>Pekerjaan aktif</h3>${jobs.map(j=>`<article class="job114"><div><strong>${E(j.title)}</strong><small>${E(labelName114(j.member))} · ${E(j.stage||'Dalam proses')}</small></div>${B114('Buka ↗','job',j.key,'small')}</article>`).join('')||'<p>Tidak ada pekerjaan aktif.</p>'}</section><section class="section114"><h3>Aktivitas akses terbaru</h3>${history114(id)}</section>${u.status==='invited'?`<section class="section114"><h3>Undangan</h3><p>${u.invite.status==='revoked'?'Undangan telah dicabut. Kirim ulang untuk membuat undangan baru.':'Undangan siap dicoba melalui aktivasi simulasi.'}</p><div class="button-row114">${B114('Kirim ulang undangan','resend',id,'small')}${u.invite.status==='valid'?B114('Cabut undangan','revoke',id,'text')+B114('Coba aktivasi','activate-preview',id,'primary'):''}</div></section>`:''}`,u.status==='active'?B114('Nonaktifkan akun','disable',id,'danger114'):u.status==='inactive'?B114('Aktifkan kembali','reactivate',id,'primary'):'',id)}
function roleDetail114(id){if(!super114())return;const r=Staff114.role(model114(),id);if(!r)return;const users=model114().users.filter(u=>u.role===id);drawer114(r.name,`<section class="hero114"><span class="role-icon114">${icon('shield')}</span><div><h3>${E(r.name)}</h3><p>${E(r.description)}</p>${r.archived?statusBadge111('Diarsipkan','neutral'):statusBadge111('Peran aktif','green')}</div></section><dl class="facts114"><div><dt>Pengguna peran</dt><dd>${users.length} staff</dd></div><div><dt>Izin</dt><dd>${r.permissions.length}</dd></div></dl><section class="section114"><h3>Staff pengguna</h3>${users.map(u=>`<div class="job114"><div><strong>${E(u.name)}</strong><small>${names114[u.status]}</small></div>${B114('Detail ↗','staff',u.id,'small')}</div>`).join('')||'<p>Belum digunakan.</p>'}</section><section class="section114"><h3>Kewenangan</h3>${permissionList114(r.permissions)}</section><section class="section114"><h3>Riwayat perubahan</h3>${history114(r.id)}</section>`,r.archived?'':B114('Ubah peran','edit-role',id,'primary')+B114('Arsipkan peran','archive',id,'text'),id)}
function labelsField114(u){return `<label>Cakupan data<select name="scope"><option value="all" ${u.scope==='all'?'selected':''}>Seluruh label</option><option value="selected" ${u.scope==='selected'?'selected':''}>Label tertentu</option></select></label><fieldset class="label-options114" ${u.scope==='all'?'hidden':''}><legend>Label yang dapat diakses</legend>${ten.members.filter(m=>!m.claimedLabel105).map(m=>`<label class="check114"><input type="checkbox" name="labels" value="${E(m.id)}" ${(u.labels||[]).includes(m.id)?'checked':''}>${E(m.name)}</label>`).join('')}</fieldset>`}
