function accessForm114(id,kind='save-access'){const u=user114(id);drawer114(kind==='reactivate'?'Aktifkan kembali':'Ubah akses',`<form data-form114="access" data-kind="${kind}" data-id="${u.id}" data-version="${u.version}"><div class="identity-note114"><strong>${E(u.name)}</strong><span>${E(u.email)}</span></div>${u.super?'<p>Kewenangan Super Admin dipertahankan. Pekerjaan lama tidak diambil kembali otomatis.</p>':roleSelect114(u.role)+labelsField114(u)}<div id="role-description114">${permissionList114(Staff114.role(model114(),u.role)?.permissions||[])}</div>${error114()}<div class="form-foot114">${B114('Kembali','staff',id,'text')}${submit114('Tinjau perubahan')}</div></form>`,'',id)}
